WITH sales_agg AS ( SELECT cs_warehouse_sk, SUM(cs_net_profit) AS total_net_profit, AVG(cs_quantity) AS avg_quantity FROM catalog_sales WHERE cs_sold_date_sk >= 20200101 GROUP BY cs_warehouse_sk ), inv_agg AS ( SELECT inv_warehouse_sk, SUM(inv_quantity_on_hand) AS total_inventory_qty FROM inventory WHERE inv_date_sk BETWEEN 20200101 AND 20201231 GROUP BY inv_warehouse_sk ) SELECT w.w_warehouse_name, w.w_city, COALESCE(s.total_net_profit, 0) AS total_net_profit, COALESCE(s.avg_quantity, 0) AS avg_quantity, COALESCE(i.total_inventory_qty, 0) AS total_inventory_qty, CASE WHEN COALESCE(s.total_net_profit, 0) > 0 THEN 'Profit' WHEN COALESCE(s.total_net_profit, 0) < 0 THEN 'Loss' ELSE 'Break-even' END AS profit_status, ROW_NUMBER() OVER (ORDER BY COALESCE(s.total_net_profit, 0) DESC) AS profit_rank FROM warehouse w LEFT JOIN sales_agg s ON w.w_warehouse_sk = s.cs_warehouse_sk LEFT JOIN inv_agg i ON w.w_warehouse_sk = i.inv_warehouse_sk WHERE w.w_state = 'CA' ORDER BY profit_rank LIMIT 10
